package io.github.miklires.mclans.storage;
import static org.junit.jupiter.api.Assertions.*;import io.github.miklires.mclans.api.ClanRole;import java.time.Instant;import java.util.UUID;import org.junit.jupiter.api.Test;
class ClanRepositoryTest {
 @Test void lifecyclePreservesRolesAndMemberLimit(){try(ClanRepository r=new ClanRepository("jdbc:h2:mem:lifecycle;DB_CLOSE_DELAY=-1")){UUID owner=UUID.randomUUID(),member=UUID.randomUUID(),extra=UUID.randomUUID();var clan=r.create(owner,"Owner","Knights","KNG").join();assertEquals(ClanRole.OWNER,r.member(owner).join().orElseThrow().role());r.invite(clan.id(),member,"Member",owner,Instant.now().plusSeconds(60).toEpochMilli()).join();assertTrue(r.acceptInvite(member,"Member",clan.id(),2).join());r.invite(clan.id(),extra,"Extra",owner,Instant.now().plusSeconds(60).toEpochMilli()).join();assertFalse(r.acceptInvite(extra,"Extra",clan.id(),2).join());assertFalse(r.leave(owner).join());assertTrue(r.leave(member).join());assertTrue(r.disband(clan.id(),owner).join());assertTrue(r.clanOf(owner).join().isEmpty());}}
 @Test void pvpAwardsAreRateLimitedAndBankNeverGoesNegative(){try(ClanRepository r=new ClanRepository("jdbc:h2:mem:economy;DB_CLOSE_DELAY=-1")){UUID owner=UUID.randomUUID(),victim=UUID.randomUUID();var clan=r.create(owner,"Owner","Raiders","RDR").join();assertTrue(r.awardKill(clan.id(),owner,victim,10,60_000,1).join());assertFalse(r.awardKill(clan.id(),owner,victim,10,60_000,1).join());assertTrue(r.changeBank(clan.id(),owner,100,"deposit").join());assertFalse(r.changeBank(clan.id(),owner,-101,"withdraw").join());assertTrue(r.changeBank(clan.id(),owner,-100,"withdraw").join());}}
}
